// Generated by ESDD from examples/order-cancel.usecase.yaml RULE-001 (source.version "v1").
// Product code: the component calls this function, and cancellation-terms.test.ts tests it.
// RULE-001 gives no fee amount for a cancellation after packing, so none is computed
// here — the amount is on the question list (order-cancel.decision.yaml).

export type CancelableState = "PLACED" | "PACKED";

export type CancellationTerms =
  | { kind: "free"; feeCents: 0 }
  // notice is a bindings literal key; the screen resolves it to the copy
  | { kind: "fee_notice"; notice: "cancellation_fee_notice" };

export function cancellationTerms(state: CancelableState): CancellationTerms {
  switch (state) {
    case "PLACED":
      return { kind: "free", feeCents: 0 };
    case "PACKED":
      return { kind: "fee_notice", notice: "cancellation_fee_notice" };
  }
}
